using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1DeskQuality {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_DeskPropRefinement/";static string O=>R+"/Docs/Review/2026-11-12_B1_DeskProps/";static Vector3 V(JToken q)=>new Vector3((float)q[0],(float)q[1],(float)q[2]);
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");var models=JObject.Parse(File.ReadAllText(H+"models.json"));var plan=JObject.Parse(File.ReadAllText(H+"plan.json"));var errors=new List<string>();var rows=new List<object>();var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;int orientations=0;long bytes=0;
  foreach(var q in models){string path=(string)q.Value["asset"];bytes+=new FileInfo(Path.GetFullPath(Path.Combine(Application.dataPath,"..",path))).Length;var meshes=AssetDatabase.LoadAllAssetsAtPath(path).OfType<Mesh>().OrderBy(m=>m.name).ToArray();if(meshes.Length!=3)errors.Add("LOD count "+q.Key);foreach(var m in meshes){var vs=m.vertices;var ns=m.normals;var ts=m.triangles;int nonFinite=vs.Count(v=>!float.IsFinite(v.x)||!float.IsFinite(v.y)||!float.IsFinite(v.z)),zero=0,reversed=0;for(int i=0;i<ts.Length;i+=3){var cross=Vector3.Cross(vs[ts[i+1]]-vs[ts[i]],vs[ts[i+2]]-vs[ts[i]]);if(cross.sqrMagnitude<1e-24f)zero++;else if(ns.Length==vs.Length&&Vector3.Dot(cross.normalized,(ns[ts[i]]+ns[ts[i+1]]+ns[ts[i+2]]).normalized)<-.5f)reversed++;}rows.Add(new{name=m.name,vertices=vs.Length,triangles=ts.Length/3,nonFinite,zeroArea=zero,reversedNormals=reversed,readable=m.isReadable});if(nonFinite!=0||zero!=0||m.isReadable)errors.Add("Mesh invalid "+m.name+" zero="+zero);}}
  foreach(var q in plan["targets"]){var data=models[(string)q["variant"]];var features=data["features"];var keyboard=features.FirstOrDefault(f=>(string)f["kind"]=="keyboard");var mouse=features.FirstOrDefault(f=>(string)f["kind"]=="mouse");if(keyboard==null)continue;var t=root.Find("B1_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);var delta=t.TransformPoint(V(mouse["center"]))-t.TransformPoint(V(keyboard["center"]));float right=Vector3.Dot(delta,t.TransformDirection(Vector3.left));if(right<.25f)errors.Add("Mouse not on worker right "+t.name);orientations++;}
  var result=new{models=models.Count,lodMeshes=rows.Count,modelBytes=bytes,checkedRightHandedStations=orientations,errors,meshes=rows};File.WriteAllText(O+"quality.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{result.models,result.lodMeshes,result.modelBytes,result.checkedRightHandedStations,errors,reversedNormals=rows.Sum(r=>(int)r.GetType().GetProperty("reversedNormals").GetValue(r))};}
}
